"""Drone mode checks (camera and LiDAR): python3 -I test/uav_check.py planner/index.html"""
import sys,json,os
from playwright.sync_api import sync_playwright
f=os.path.abspath(sys.argv[1] if len(sys.argv)>1 else 'planner/index.html')
INIT="""window.__dl=[];window.open=()=>null;const _ck=HTMLAnchorElement.prototype.click;HTMLAnchorElement.prototype.click=function(){if(this.download&&this.href.startsWith('blob:')){const n=this.download;fetch(this.href).then(r=>r.text()).then(t=>window.__dl.push({n,t}));return}return _ck.call(this)};"""
bad=[]
def ok(c,m):
    print(('ok   ' if c else 'FAIL ')+m)
    if not c:bad.append(m)
with sync_playwright() as p:
    b=p.chromium.launch();c=b.new_context(viewport={'width':1400,'height':900},locale='en-US');c.route(lambda u: not u.startswith('file:'), lambda r: r.abort());c.add_init_script(INIT)
    pg=c.new_page();e=[];pg.on('pageerror',lambda x:e.append(str(x)));pg.goto('file://'+f+'?type=uav&shape=area');pg.wait_for_timeout(2500);pg.evaluate("setLang('en')")
    ev=pg.evaluate
    ok(ev("$('spd').parentElement.id")=='uvSpd','speed input moves into the drone section')
    ok(all(ev(f"!!document.querySelector('details[data-sec={k}]').hidden") for k in ['turn','iho','coast']),'vessel sections hidden')
    ev("$('uvCam').value='m3e';$('uvCam').dispatchEvent(new Event('change'));$('uvH').value=100;$('uvFO').value=75;$('uvSO').value=65;$('spd').value=19.44;$('spd').dispatchEvent(new Event('input'))");pg.wait_for_timeout(500)
    ok(ev("$('uvGsd').textContent")=='2.66 cm/px','GSD 2.66 cm/px for the Mavic 3E at 100 m')
    ok(abs(ev("params().S")-100*17.3/12.3*.35)<.01,'line spacing = footprint x (1 - side overlap)')
    ok(ev("$('uvPh').textContent").startswith('26.4 m'),'photo distance = along footprint x (1 - forward overlap)')
    ok(ev("[...new Set(R.turns.map(t=>t.ty))].join()")=='u','tight turns between lines')
    ev("$('uvH').value=150;$('uvH').dispatchEvent(new Event('input'))");pg.wait_for_timeout(400)
    ok('above 120 m' in ev("$('chk').innerText"),'height warning above 120 m')
    ev("$('uvH').value=100;$('uvFO').value=95;$('uvMI').value=2;$('uvH').dispatchEvent(new Event('input'))");pg.wait_for_timeout(400)
    ok('faster than the camera allows' in ev("$('chk').innerText"),'photo interval warning')
    ev("$('uvFO').value=75;$('uvMI').value=0.7;$('uvH').dispatchEvent(new Event('input'))");pg.wait_for_timeout(400)
    ev("window.__dl=[];$('eQgc').click()");pg.wait_for_timeout(600);it=json.loads(ev("window.__dl[0].t"))['mission']['items']
    ok(it[0]['params'][6]==100 and [x['params'][0] for x in it if x['command']==206]==[26.42,0],'QGroundControl plan: height and camera trigger on/off')
    ok([x['doJumpId'] for x in it]==list(range(1,len(it)+1)),'QGroundControl item numbering')
    ev("window.__dl=[];$('eMp').click()");pg.wait_for_timeout(600);mp=ev("window.__dl[0].t").split('\n')
    ok(mp[2].split('\t')[10]=='100' and mp[3].split('\t')[3]=='206','Mission Planner: height and camera trigger')
    # LiDAR payload: Zenmuse L2 at 100 m, 10 m/s, 50 % side overlap
    ev("$('uvPay').value='lidar';$('uvPay').dispatchEvent(new Event('change'));$('uvLid').value='l2';$('uvLid').dispatchEvent(new Event('change'));$('uvH').value=100;$('uvLSO').value=50;$('uvLT').value=100;$('spd').value=19.4384;$('spd').dispatchEvent(new Event('input'))");pg.wait_for_timeout(500)
    import math
    sw=2*100*math.tan(math.radians(35))
    ok(abs(ev("params().W")-sw)<.01 and abs(ev("params().S")-sw*.5)<.01,f'LiDAR swath 2H tan(FOV/2) = {sw:.1f} m, spacing = swath x (1 - side overlap)')
    d1=240000/(10*sw)
    ok(ev("$('uvLDn').textContent")==f"{round(d1/.5)} pts/m² ({round(d1)} per pass)",f'point density = rate / (speed x swath) = {d1:.0f} per pass, {d1/.5:.0f} with overlap')
    ok(all(ev("[...document.querySelectorAll('#uvBox .uv-cam')].every(x=>x.offsetParent===null)") for _ in [0]) and ev("[...document.querySelectorAll('#uvBox .uv-lid')].every(x=>x.offsetParent!==null)"),'camera fields hidden, LiDAR fields shown')
    chk=ev("$('chk').innerText")
    ok('within the 250 m detection range' in chk and 'meets the 100 pts/m² target' in chk,'LiDAR plan checks: slant range and density target')
    ev("$('uvLT').value=500;$('uvLT').dispatchEvent(new Event('input'))");pg.wait_for_timeout(400);chk=ev("$('chk').innerText")
    vmax=240000/(500*.5*sw)
    ok(f'fly at {vmax:.1f} m/s or slower' in chk,f'density below target: suggests {vmax:.1f} m/s')
    ev("$('uvLT').value=100;$('uvH').value=230;$('uvH').dispatchEvent(new Event('input'))");pg.wait_for_timeout(400);chk=ev("$('chk').innerText")
    ok('slant range is' in chk and 'beyond the 250 m detection range' in chk,'slant range beyond the detection range at the swath edge')
    ev("$('uvH').value=100;$('uvH').dispatchEvent(new Event('input'))");pg.wait_for_timeout(300)
    ev("window.__dl=[];$('eQgc').click();$('eMp').click()");pg.wait_for_timeout(600);dl=ev("window.__dl")
    it=json.loads([d for d in dl if d['n'].endswith('.plan')][0]['t'])['mission']['items'];mpt=[d for d in dl if d['n'].endswith('.waypoints')][0]['t']
    ok(it[0]['params'][6]==100 and not any(x['command']==206 for x in it) and '\t206\t' not in mpt,'LiDAR waypoint exports: height, no camera trigger')
    ok(ev("SWP_SENSORTXT").startswith('DJI Zenmuse L2, 343 pts/m²'),'report sensor line names the LiDAR and density')
    ev("$('uvLid').value='l3';$('uvLid').dispatchEvent(new Event('change'))");pg.wait_for_timeout(300)
    ok(ev("[g('uvLF'),g('uvLR'),g('uvLX')]")==[80,350000,700],'Zenmuse L3 preset (80°, 350 kHz, 700 m)')
    n=ev("R.lines.length");pg.reload();pg.wait_for_timeout(3000)
    ok(ev("$('uvPay').value")=='lidar' and ev("$('uvLid').value")=='l3' and ev("R.lines.length")==n and ev("[...document.querySelectorAll('#uvBox .uv-lid')].every(x=>x.offsetParent!==null)"),'LiDAR payload restored after reload')
    ev("$('uvPay').value='cam';$('uvPay').dispatchEvent(new Event('change'))");pg.wait_for_timeout(400)
    ok(ev("$('uvGsd').textContent")=='2.66 cm/px' and abs(ev("params().S")-100*17.3/12.3*.35)<.01,'back to the camera: same plan as before')
    # preset lists: every camera and LiDAR preset has an option and every option a preset
    ok(ev("(()=>{const o=[...$('uvCam').options].map(x=>x.value).filter(v=>v!='custom').sort().join(),k=Object.keys(UV_CAM).sort().join();return o==k})()") and ev("Object.keys(UV_CAM).length")>=22,f'{ev("Object.keys(UV_CAM).length")} camera presets, each with an option')
    ok(ev("(()=>{const o=[...$('uvLid').options].map(x=>x.value).filter(v=>v!='custom').sort().join(),k=Object.keys(UV_LID).sort().join();return o==k})()") and ev("Object.keys(UV_LID).length")>=17,f'{ev("Object.keys(UV_LID).length")} LiDAR presets, each with an option')
    ev("$('uvPay').value='cam';$('uvPay').dispatchEvent(new Event('change'));$('uvCam').value='p1_24';$('uvCam').dispatchEvent(new Event('change'));$('uvH').value=110;$('uvH').dispatchEvent(new Event('input'))");pg.wait_for_timeout(300)
    ok(abs(ev("uvGeo().gsd")*100-110/55)<0.05,'Zenmuse P1 24 mm: GSD = H/55 cm (DJI) at 110 m')
    ev("$('uvCam').value='ixm35';$('uvCam').dispatchEvent(new Event('change'))");pg.wait_for_timeout(200)
    ok(ev("[g('uvSW'),g('uvF'),g('uvIW'),g('uvMI')]")==[43.9,35,11664,0.34],'Phase One iXM-100 35 mm preset')
    ev("$('uvCam').value='p5_35';$('uvCam').dispatchEvent(new Event('change'));$('uvH').value=120;$('uvH').dispatchEvent(new Event('input'))");pg.wait_for_timeout(300)
    ok(abs(ev("uvGeo().gsd")*100-1.18)<0.02,'Phase One P5 35 mm: 1.18 cm at 120 m (Quantum Systems)')
    ev("$('uvCam').value='anafi';$('uvCam').dispatchEvent(new Event('change'))");pg.wait_for_timeout(200)
    ok(ev("[g('uvIW'),g('uvMI')]")==[8000,1],'Parrot ANAFI Ai preset (8000 px, 1 photo/s)')
    ev("$('uvPay').value='lidar';$('uvPay').dispatchEvent(new Event('change'));$('uvLid').value='vux120';$('uvLid').dispatchEvent(new Event('change'));$('uvH').value=100;$('uvH').dispatchEvent(new Event('input'))");pg.wait_for_timeout(300)
    ok(abs(ev("uvGeo().across")-2*100*math.tan(math.radians(50)))<0.5,'RIEGL VUX-120: swath 2·H·tan 50° at 100 m')
    ev("$('uvLid').value='wingtra';$('uvLid').dispatchEvent(new Event('change'))");pg.wait_for_timeout(300)
    ok('80 m' in ev("$('sumBox')?$('sumBox').textContent:document.body.textContent"),'Wingtra (XT32M2X): warns beyond 80 m on dark ground at 100 m')
    ev("$('uvPay').value='cam';$('uvPay').dispatchEvent(new Event('change'))");pg.wait_for_timeout(200)
    ev("$('uvCam').value='m3e';$('uvCam').dispatchEvent(new Event('change'));$('uvH').value=100;$('uvH').dispatchEvent(new Event('input'))");pg.wait_for_timeout(300)
    ok(ev("SWP_SHEET_TITLE")=='DRONE FLIGHT PLAN','sheet title')
    ev("$('svT').value='mbes';$('svT').dispatchEvent(new Event('change'))");pg.wait_for_timeout(600)
    ok(ev("$('spd').closest('details').dataset.sec")=='iho' and ev("$('spd').value")=='6','back to multibeam: speed returns with the vessel value')
    ok(ev("$('slow').checked") and ev("$('svpI').value")=='4','vessel settings untouched')
    ev("window.__dl=[];$('eQgc').click()");pg.wait_for_timeout(600);it=json.loads(ev("window.__dl[0].t"))['mission']['items']
    ok(all(x['command']==16 and x['params'][6]==0 for x in it),'multibeam waypoint export unchanged')
    ok(not e,'no page errors '+str(e));b.close()
print('ALL OK' if not bad else f'{len(bad)} FAILED');sys.exit(1 if bad else 0)
